// ─────────────────────────────────────────────────────────────────────────
//  01 · fake the payment gateway★★☆
//  concepts: fakes at your own boundary · idempotency keys · a timeout after the charge
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    enum Status { APPROVED, DECLINED }

    record Charge(String id, String card, long cents, Status status) {}

    /** Our own interface around the card provider: the boundary we fake. */
    interface PaymentGateway {
        Charge charge(String idempotencyKey, String card, long cents);
    }

    static class GatewayTimeout extends RuntimeException {
        GatewayTimeout(String message) { super(message); }
    }

    /** A fake that keeps the real gateway's rules. */
    static class FakeGateway implements PaymentGateway {
        final Set<String> declinedCards = new HashSet<>();
        private final Map<String, Charge> byKey = new HashMap<>();
        private final List<Charge> made = new ArrayList<>();
        private boolean loseNext;

        void loseNextResponse() {
            loseNext = true;
        }

        public Charge charge(String idempotencyKey, String card, long cents) {
            if (cents <= 0) throw new IllegalArgumentException("amount must be positive");
            Charge earlier = byKey.get(idempotencyKey);
            if (earlier != null) return earlier;
            Status status = declinedCards.contains(card) ? Status.DECLINED : Status.APPROVED;
            Charge charge = new Charge("ch_" + (made.size() + 1), card, cents, status);
            byKey.put(idempotencyKey, charge);
            made.add(charge);
            if (loseNext) {
                loseNext = false;
                throw new GatewayTimeout("read timed out after the provider accepted the charge");
            }
            return charge;
        }

        List<Charge> charges() {
            return List.copyOf(made);
        }
    }

    /** Given: the code under test. It retries once on a timeout, with the same key. */
    static class Checkout {
        private final PaymentGateway gateway;
        Checkout(PaymentGateway gateway) { this.gateway = gateway; }

        String pay(String orderId, String card, long cents) {
            String key = "order-" + orderId;
            Charge charge;
            try {
                charge = gateway.charge(key, card, cents);
            } catch (GatewayTimeout timeout) {
                charge = gateway.charge(key, card, cents);
            }
            return charge.status() == Status.APPROVED ? "paid " + charge.id() : "declined";
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("new charges get the next id and are recorded in order", () -> {
            var gw = new FakeGateway();
            var a = gw.charge("k1", "card-1", 500);
            var b = gw.charge("k2", "card-2", 700);
            eq(List.of(a.id(), b.id(), gw.charges().size()), List.of("ch_1", "ch_2", 2));
        });
        test("a declined card gives a DECLINED charge, and checkout says so", () -> {
            var gw = new FakeGateway();
            gw.declinedCards.add("card-x");
            eq(List.of(new Checkout(gw).pay("7", "card-x", 1200), gw.charges().get(0).status()), List.of("declined", Status.DECLINED));
        });
        test("a repeated idempotency key returns the first charge without charging again", () -> {
            var gw = new FakeGateway();
            var first = gw.charge("order-7", "card-1", 1200);
            var again = gw.charge("order-7", "card-1", 1200);
            eq(List.of(again, gw.charges().size()), List.of(first, 1));
        });
        test("a lost response is still a charge: the call throws, but the money moved", () -> {
            var gw = new FakeGateway();
            gw.loseNextResponse();
            raises(GatewayTimeout.class, () -> gw.charge("order-7", "card-1", 1200));
            eq(gw.charges(), List.of(new Charge("ch_1", "card-1", 1200, Status.APPROVED)));
            eq(gw.charge("order-8", "card-1", 300).id(), "ch_2");   // only that one response was lost
        });
        test("checkout's retry after a lost response pays exactly once", () -> {
            var gw = new FakeGateway();
            gw.loseNextResponse();
            eq(List.of(new Checkout(gw).pay("7", "card-1", 1200), gw.charges().size()), List.of("paid ch_1", 1));
        });
        test("a list handed out earlier does not change when more charges are made", () -> {
            var gw = new FakeGateway();
            gw.charge("k1", "card-1", 500);
            var before = gw.charges();
            gw.charge("k2", "card-1", 600);
            eq(List.of(before.size(), gw.charges().size()), List.of(1, 2));
        });
        test("a non-positive amount is refused and records nothing (boundary)", () -> {
            var gw = new FakeGateway();
            raises(IllegalArgumentException.class, () -> gw.charge("k1", "card-1", 0), "amount must be positive");
            eq(gw.charges().size(), 0);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Record first, then decide whether to hand the result back:

```java
if (cents <= 0) throw new IllegalArgumentException("amount must be positive");
Charge earlier = byKey.get(idempotencyKey);
if (earlier != null) return earlier;
Status status = declinedCards.contains(card) ? Status.DECLINED : Status.APPROVED;
Charge charge = new Charge("ch_" + (made.size() + 1), card, cents, status);
byKey.put(idempotencyKey, charge);
made.add(charge);
if (loseNext) { loseNext = false; throw new GatewayTimeout("..."); }
return charge;
```

`charges()` returns `List.copyOf(made)`. The tests catch the fakes that make a retry look safe or unsafe for the wrong reason: one without idempotency (the retry charges twice), one whose timeout fires BEFORE recording the charge (the money-moved test sees no charge), one that keeps losing every later response (the next new charge throws too), and one that hands out its live list (an earlier snapshot grows).

