// ─────────────────────────────────────────────────────────────────────────
//  02 · a mock by hand★★★
//  concepts: java.lang.reflect.Proxy · equals argument matching · default answers · last stub wins
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.lang.reflect.*;
import java.util.*;

class Exercise {

    interface OrderRepo {
        Optional<String> findByEmail(String email);
        List<String> findOpen();
        Set<String> tags();
        Map<String, Integer> stock();
        int count();
        Long total();
        boolean active();
        String name();
        void save(String order);
    }

    static final class Mock<T> {
        private record Call(String method, List<Object> args) {}

        private final Map<Call, Object> stubs = new HashMap<>();
        private final List<Call> recorded = new ArrayList<>();
        private final T proxy;

        private Mock(Class<T> type) {
            InvocationHandler handler = (self, method, args) -> {
                if (method.getDeclaringClass() == Object.class) {
                    return switch (method.getName()) {
                        case "toString" -> "Mock for " + type.getSimpleName();
                        case "equals" -> self == args[0];
                        default -> System.identityHashCode(self);
                    };
                }
                var call = new Call(method.getName(), args == null ? List.of() : Arrays.asList(args));
                recorded.add(call);
                return stubs.containsKey(call) ? stubs.get(call) : defaultFor(method.getReturnType());
            };
            proxy = type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] { type }, handler));
        }

        static Object defaultFor(Class<?> t) {
            if (t == List.class || t == Collection.class) return List.of();
            if (t == Set.class) return Set.of();
            if (t == Map.class) return Map.of();
            if (t == Optional.class) return Optional.empty();
            if (t == boolean.class || t == Boolean.class) return false;
            if (t == int.class || t == Integer.class) return 0;
            if (t == long.class || t == Long.class) return 0L;
            if (t == short.class || t == Short.class) return (short) 0;
            if (t == byte.class || t == Byte.class) return (byte) 0;
            if (t == double.class || t == Double.class) return 0.0;
            if (t == float.class || t == Float.class) return 0.0f;
            if (t == char.class || t == Character.class) return '\0';
            return null;
        }

        static <T> Mock<T> of(Class<T> type) {
            return new Mock<>(type);
        }

        T object() {
            return proxy;
        }

        Mock<T> when(String method, List<Object> args, Object result) {
            stubs.put(new Call(method, List.copyOf(args)), result);
            return this;
        }

        int calls(String method, List<Object> args) {
            var wanted = new Call(method, args);
            return (int) recorded.stream().filter(wanted::equals).count();
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a stub answers a call whose arguments are equal", () -> {
            var m = Mock.of(OrderRepo.class);
            m.when("findByEmail", List.of("ana@x.io"), Optional.of("Ana"));
            eq(m.object().findByEmail(new String("ana@x.io")), Optional.of("Ana"));
        });
        test("other arguments get the default answer: an empty Optional", () -> {
            var m = Mock.of(OrderRepo.class);
            m.when("findByEmail", List.of("ana@x.io"), Optional.of("Ana"));
            eq(m.object().findByEmail("ANA@x.io"), Optional.empty());
        });
        test("unstubbed collections are empty, never null", () -> {
            var repo = Mock.of(OrderRepo.class).object();
            eq(List.of(repo.findOpen(), repo.tags(), repo.stock()), List.of(List.of(), Set.of(), Map.of()));
        });
        test("primitives and their wrappers default to zero or false, other objects to null", () -> {
            var repo = Mock.of(OrderRepo.class).object();
            eq(Arrays.asList(repo.count(), repo.total(), repo.active(), repo.name()), Arrays.asList(0, 0L, false, null));
        });
        test("the last stubbing of the same call wins", () -> {
            var m = Mock.of(OrderRepo.class);
            m.when("count", List.of(), 3).when("count", List.of(), 5);
            eq(m.object().count(), 5);
        });
        test("calls are counted per method and per arguments, void ones included", () -> {
            var m = Mock.of(OrderRepo.class);
            var repo = m.object();
            repo.save("o-1");
            repo.save("o-1");
            repo.save("o-2");
            repo.findOpen();
            eq(List.of(m.calls("save", List.of("o-1")), m.calls("save", List.of("o-2")), m.calls("findOpen", List.of()), m.calls("count", List.of())), List.of(2, 1, 1, 0));
        });
        test("toString names the mock, equals is identity, and neither is recorded (boundary)", () -> {
            var m = Mock.of(OrderRepo.class);
            var repo = m.object();
            eq(List.of(repo.toString(), repo.equals(repo), repo.equals(Mock.of(OrderRepo.class).object()), m.calls("toString", List.of())), List.of("Mock for OrderRepo", true, false, 0));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
One handler does everything: answer the `Object` methods, record the call, then look up a stub or fall back to the default for the return type:

```java
if (method.getDeclaringClass() == Object.class) { /* toString, equals, hashCode */ }
var call = new Call(method.getName(), args == null ? List.of() : Arrays.asList(args));
recorded.add(call);
return stubs.containsKey(call) ? stubs.get(call) : defaultFor(method.getReturnType());
```

`Call` is a record, so stub lookup and counting use `equals` on the method name and the argument list. `defaultFor` checks the collection types, `Optional`, then each primitive and its wrapper. The tests catch the plausible wrong mocks: returning `null` for collections (the NPE Mockito saves you from), matching stubs by method name only (the wrong email finds Ana), counting calls by name only, `null` for wrapper types such as `Long`, and the first stubbing winning.
